def ability_name(effect_id):
    """The ability's in-game name, or None for an id off the table."""
    rec = ABILITY.get(effect_id)
    return rec[0] if rec else None


def target_mode(effect_id):
    """Record +1. The client still reads this LIVE when it aims a trap;
    this copy is for gen-side and test-side reasoning only."""
    rec = ABILITY.get(effect_id)
    return rec[1] if rec else None
